function parseJsonSeguro(raw) {
    if (raw && typeof raw === 'object')
        return raw;
    const texto = String(raw || '')
        .replace(/`{3}json/gi, '')
        .replace(/`{3}/g, '')
        .trim();
    try {
        return JSON.parse(texto);
    }
    catch (e) { }
    const match = texto.match(/\{[\s\S]*\}/);
    if (match) {
        try {
            return JSON.parse(match[0]);
        }
        catch (e) { }
    }
    return {};
}
const raw = $input.first().json.output || $input.first().json;
const parsed = parseJsonSeguro(raw);
let entregas = Array.isArray(parsed.entregas) ? parsed.entregas : [];
if (entregas.length === 0) {
    const texto = parsed.resposta ||
        parsed.mensagem ||
        (Array.isArray(parsed.mensagens) ? parsed.mensagens.join('\n\n') : '');
    if (texto) {
        entregas = [{ tipo: 'texto', texto }];
    }
}
entregas = entregas
    .filter(e => e && e.tipo)
    .map(e => {
    if (e.tipo === 'texto') {
        return { tipo: 'texto', texto: String(e.texto || e.text || e.mensagem || '').trim() };
    }
    if (e.tipo === 'imagem') {
        return {
            tipo: 'imagem',
            url: String(e.url || e.media_url || e.url_foto || '').trim(),
            legenda: String(e.legenda || e.caption || '').trim()
        };
    }
    return e;
})
    .filter(e => {
    if (e.tipo === 'texto')
        return !!e.texto;
    if (e.tipo === 'imagem')
        return !!e.url;
    return true;
});
const handoffBruto = parsed.handoff || {};
return [
    {
        json: {
            acao: entregas.length ? 'entregar' : 'sem_resposta',
            modulo: parsed.modulo || 'geral',
            entregas,
            handoff: {
                necessario: handoffBruto.necessario === true,
                motivo: String(handoffBruto.motivo || ''),
                prioridade: String(handoffBruto.prioridade || 'normal'),
                resumo_para_equipa: String(handoffBruto.resumo_para_equipa || ''),
                mensagem_para_cliente: String(handoffBruto.mensagem_para_cliente || '')
            },
            followup: parsed.followup || { necessario: false, motivo: '', data_sugerida: '' },
            operacoes: parsed.operacoes || {},
            contexto_actualizado: parsed.contexto_actualizado || {},
            erro: parsed.erro || ''
        }
    }
];

